/// <summary>
/// The <c>METCBCTInvoicePostingService</c> class handles the chargethrough invoice processing operations through Sys Operation Framework.
/// </summary>
public class METCBCTInvoicePostingService extends SysOperationServiceBase
{
    boolean isExecutionModeSynchronous;

}

Method.Source:
    /// <summary>
    /// Called from class <c>METCBCTInvoicePosting</c> and form METCBCTInvoiceForm
    /// </summary>
    /// <param name = "_invoicePostingContractUI"><c>METCBCTInvoicePostingContractUI</c> contract class</param>
    public void processFromUI(METCBCTInvoicePostingContractUI _invoicePostingContractUI)
    {
        container           packedCTInvoiceTableList;
        SysRecordSortedList cbCtInvoiceHeaderTableList;
        
        packedCTInvoiceTableList = _invoicePostingContractUI.parmInvoiceList();

        cbCtInvoiceHeaderTableList = new SysRecordSortedList(tableNum(METCBCTInvoiceHeaderTable));
        cbCtInvoiceHeaderTableList.sortOrder(fieldNum(METCBCTInvoiceHeaderTable, Number), fieldNum(METCBCTInvoiceHeaderTable, RecId));
        cbCtInvoiceHeaderTableList.unpack(packedCTInvoiceTableList);

        this.processCTInvoiceHeaderMulti(cbCtInvoiceHeaderTableList);
    }

    /// <summary>
    /// Process the charge through invoice.
    /// </summary>
    /// <param name="_invoicePostingContract">
    /// An object of the <c>METCBCTInvoicePostingContract</c> class.
    /// </param>
    public void process(METCBCTInvoicePostingContract _invoicePostingContract)
    {
        BatchHeader                     ctInvoicePostingBatchHeader;
        Query                           query;
        QueryRun                        queryRun;
        SysRecordSortedList             cbCtInvoiceHeaderTableList;
        METCBCTInvoiceHeaderTable       ctInvoiceHeaderTable;
        METCBCTInvoicePostingContract   cbCTInvoicePostingContract;
        METCBCTInvoicePostingController cbCTInvoicePostingController;
        container                       packedCTInvoiceTableList;
        int                             bundleSize;
        int                             invoiceCounter;
        
        METThreadCount threadCount = _invoicePostingContract.parmThreadCount();
        Int            numOfChargeThrough = this.countChargeThrough(new Query(SysOperationHelper::base64Decode(_invoicePostingContract.parmPackedQuery())));
        bundleSize      = real2int(roundUp((numOfChargeThrough / threadCount), 1.0));

        if (!ctInvoicePostingBatchHeader)
        {
            ctInvoicePostingBatchHeader = BatchHeader::getCurrentBatchHeader();
        }

        query = new Query(SysOperationHelper::base64Decode(_invoicePostingContract.parmPackedQuery()));
        queryRun = new QueryRun(query);
            
        cbCtInvoiceHeaderTableList = new SysRecordSortedList(tableNum(METCBCTInvoiceHeaderTable));
        cbCtInvoiceHeaderTableList.sortOrder(fieldNum(METCBCTInvoiceHeaderTable, Number), fieldNum(METCBCTInvoiceHeaderTable, RecId));

        while (queryRun.next())
        {
            ctInvoiceHeaderTable = queryRun.get(tableNum(METCBCTInvoiceHeaderTable)) as METCBCTInvoiceHeaderTable;

            cbCtInvoiceHeaderTableList.ins(ctInvoiceHeaderTable);
            invoiceCounter++;

            if (invoiceCounter == bundleSize)
            {
                packedCTInvoiceTableList = cbCtInvoiceHeaderTableList.pack();
                cbCTInvoicePostingController = METCBCTInvoicePostingController::construct();
                cbCTInvoicePostingController.parmMethodName(methodStr(METCBCTInvoicePostingService, processTask));
                cbCTInvoicePostingController.parmDialogCaption("@MET:CTProcessBatchTask");

                cbCTInvoicePostingContract = cbCTInvoicePostingController.getDataContractObject();
                cbCTInvoicePostingContract.parmInvoiceList(packedCTInvoiceTableList);

                ctInvoicePostingBatchHeader.addRunTimeTask(cbCTInvoicePostingController, this.getCurrentBatchTask().RecId);

                cbCtInvoiceHeaderTableList = new SysRecordSortedList(tableNum(METCBCTInvoiceHeaderTable));
                cbCtInvoiceHeaderTableList.sortOrder(fieldNum(METCBCTInvoiceHeaderTable, Number), fieldNum(METCBCTInvoiceHeaderTable, RecId));
                invoiceCounter = 0;
            }        
        }

        if (invoiceCounter)
        {
            packedCTInvoiceTableList = cbCtInvoiceHeaderTableList.pack();
            cbCTInvoicePostingController = METCBCTInvoicePostingController::construct();
            cbCTInvoicePostingController.parmMethodName(methodStr(METCBCTInvoicePostingService, processTask));
            cbCTInvoicePostingController.parmDialogCaption("@MET:CTProcessBatchTask");

            cbCTInvoicePostingContract = cbCTInvoicePostingController.getDataContractObject();
            cbCTInvoicePostingContract.parmInvoiceList(packedCTInvoiceTableList);

            ctInvoicePostingBatchHeader.addRunTimeTask(cbCTInvoicePostingController, this.getCurrentBatchTask().RecId);
        }

        if (ctInvoicePostingBatchHeader)
        {
            ctInvoicePostingBatchHeader.save();
        }
    }

    /// <summary>
    /// Executes as the runtime task in Charge through invoice posting.
    /// </summary>
    /// <param name="_cbCTInvoicePostingContract">
    /// Data Contract object passed from the Controller object.
    /// </param>
    public void processTask(METCBCTInvoicePostingContract _cbCTInvoicePostingContract)
    {
        container                   packedCTInvoiceTableList;
        SysRecordSortedList         cbCtInvoiceHeaderTableList;
        BatchJob                    batchJob;
        boolean                     postingSuccessful;

        packedCTInvoiceTableList = _cbCTInvoicePostingContract.parmInvoiceList();

        cbCtInvoiceHeaderTableList = new SysRecordSortedList(tableNum(METCBCTInvoiceHeaderTable));
        cbCtInvoiceHeaderTableList.sortOrder(fieldNum(METCBCTInvoiceHeaderTable, Number), fieldNum(METCBCTInvoiceHeaderTable, RecId));
        cbCtInvoiceHeaderTableList.unpack(packedCTInvoiceTableList);

        postingSuccessful = this.processCTInvoiceHeaderMulti(cbCtInvoiceHeaderTableList);

        if (!postingSuccessful)
        {
            if (this.isExecutingInBatch())
            {
                select firstonly batchJob where batchJob.RecId == this.getCurrentBatchTask().BatchJobId;
                if (batchJob.RecId)
                {
                    ttsBegin;
                    batchJob.selectForUpdate(true);
                    batchJob.Status = BatchStatus::Error;
                    batchJob.update();
                    ttsCommit;
                }
            }
        }
    }

/// <summary>
/// Sets the execution mode of the batch tasks to be synchronous.
/// </summary>
/// <param name="_isExecutionModeSynchronous">
/// A Boolean value that indicates whether to set the execution mode of the batch tasks to synchronous.
/// </param>
/// <returns>
/// true if the execution mode of batch tasks to be processed is true.
/// </returns>
public boolean setExecutionModeSynchronous(boolean _isExecutionModeSynchronous)
{
    isExecutionModeSynchronous = _isExecutionModeSynchronous;
    return isExecutionModeSynchronous;
}

    /// <summary>
    /// Post invoice for the charge through invoice
    /// </summary>
    /// <param name="_cbCtInvoiceHeaderTableList"><c>SysRecordSortedList</c>
    /// </param>
    /// <returns>True if successful; otherwise, false.</returns>
    public boolean processCTInvoiceHeaderMulti(SysRecordSortedList  _cbCtInvoiceHeaderTableList)
    {
        boolean                         ret = true, processSuccessful = true;
        METCBCTInvoiceHeaderTable       cbCTInvoiceHeaderTable;
        boolean                         haveMoreRecords;

        haveMoreRecords = _cbCtInvoiceHeaderTableList.first(cbCTInvoiceHeaderTable);

        while (haveMoreRecords)
        {
            setPrefix(strFmt("@MET:ChargeThroughPrefix", cbCTInvoiceHeaderTable.Number));
            processSuccessful = this.processCTInvoiceHeader(cbCTInvoiceHeaderTable);

            // if at least one CT process failed, return false
            if (!processSuccessful)
            {
                ret = false;
            }

            haveMoreRecords = _cbCtInvoiceHeaderTableList.next(cbCTInvoiceHeaderTable);
        }

        return ret;
    }

    /// <summary>
    /// Perform posting tasks
    /// </summary>
    /// <param name="_cbCTInvoiceHeaderTable"><c>METCBCTInvoiceHeaderTable</c></param>
    /// <returns>True if successful; otherwise, false.</returns>
    public boolean processCTInvoiceHeader(METCBCTInvoiceHeaderTable  _cbCTInvoiceHeaderTable)
    {
        METCBCTInvoiceHeaderTable   cbCTInvoiceHeaderTable = _cbCTInvoiceHeaderTable;
        SalesTable                  salesTable;
        VendInvoiceInfoTable        vendInvoiceInfoTable;
        boolean                     ret = true;

        int fromInfologLine = infologLine();
        fromInfologLine = fromInfologLine == 0 ? fromInfologLine : fromInfologLine + 1;

        // Validate
        if (this.validate(_cbCTInvoiceHeaderTable))
        {
            try
            {
                ttsbegin;                
                // Create pending vendor invoice
                vendInvoiceInfoTable = this.createPendingVendorInvoice(_cbCTInvoiceHeaderTable);

                // Create sales order
                salesTable = this.createSalesOrder(_cbCTInvoiceHeaderTable, vendInvoiceInfoTable);

                // Bug_188467_CB411_ChargethroughIssueFix
                _cbCTInvoiceHeaderTable.RefSalesId = salesTable.SalesId;
                _cbCTInvoiceHeaderTable.Status = METCBCTInvoiceStatus::Processed;

                // post SO
                this.postSalesOrderInvoice(salesTable);

                // auto submit pending vendor invoice to workflow
                this.submitVendorInvoiceWorkflow(vendInvoiceInfoTable);
        
                ttscommit;
                info(strFmt("@MET:ChargethroughInvoicePosted",cbCTInvoiceHeaderTable.Number));

                // Bug_188467_CB411_ChargethroughIssueFix
                this.updateMetCBCInvoiceHeader(_cbCTInvoiceHeaderTable);
            }
            catch (Exception::Error)
            {
                // Bug_188467_CB411_ChargethroughIssueFix
                _cbCTInvoiceHeaderTable.captureFromInfolog(fromInfologLine);
                this.updateMetCBCInvoiceHeader(_cbCTInvoiceHeaderTable, false);

                ret = false;
            }
        }
        else
        {
            // Bug_188467_CB411_ChargethroughIssueFix
            _cbCTInvoiceHeaderTable.captureFromInfolog(fromInfologLine);
            this.updateMetCBCInvoiceHeader(_cbCTInvoiceHeaderTable, false);
        }
        return ret;
    }

    /// <summary>
    /// Create sales order for the invoice
    /// </summary>
    /// <param name="_cbCTInvoiceHeaderTable">Charge through invoice header <c>METCBCTInvoiceHeaderTable</c></param>
    /// <param name="_vendInvoiceInfoTable">Pending vendor invoice header <c>VendInvoiceInfoTable</c></param>
    /// <returns>
    /// <c>SalesTable</c> sales order header record
    /// </returns>
    private SalesTable createSalesOrder(METCBCTInvoiceHeaderTable  _cbCTInvoiceHeaderTable, VendInvoiceInfoTable _vendInvoiceInfoTable)
    {        
        SalesTable  salesTable;

        salesTable = this.findOrCreateSalesOrderHeader(_cbCTInvoiceHeaderTable);

        SalesLine   salesLine;
        METCBCTInvoiceLine      cbCTInvoiceLine;

        while select cbCTInvoiceLine
            where cbCTInvoiceLine.HeaderNumber == _cbCTInvoiceHeaderTable.Number
            && cbCTInvoiceLine.VendCustType == METCBCTVendCust::Cust
        {
            //creating sales order line
            salesLine.clear();
            salesLine.initFromSalesTable(salesTable);
            salesLine.ItemId = cbCTInvoiceLine.ItemId;
            salesLine.initLineFromItemOrCategory();

            InventDim inventDim;
            inventDim.InventSiteId = cbCTInvoiceLine.InventSiteId;
            inventDim.InventLocationId = cbCTInvoiceLine.InventLocationId;

            inventDim = InventDim::findOrCreate(inventDim);
            salesLine.InventDimId = inventDim.inventDimId;

            // All lines that have a ‘negative’ amount must be copied with a negative quantity of ‘-1’ to the pending vendor invoice and sales order line
            salesLine.SalesQty = cbCTInvoiceLine.Qty >= 0 ? cbCTInvoiceLine.Qty : -cbCTInvoiceLine.Qty;

            salesLine.QtyOrdered = salesLine.calcQtyOrdered();
            salesLine.LineDisc = 0; 
          
            // CB411_412_ChargeThrough
            // If a site is not specified in the METCBCTCustomerSiteOffRemitCostCentreLink, 
            // then standard sales order charges will apply as setup in auto charges
            boolean searchMarkup = !METCBCTCustomerSiteOffRemitCostCentreLink::find(cbCTInvoiceLine.InventSiteId).CustomerOffRemittance;

            salesLine.createLine(true, // Validate
                                true,  // initFromSalesTable
                                true,  // initFromInventTable
                                true,  // calcInventQty
                                searchMarkup,  // searchMarkup
                                false  // searchPrice
                                );

            salesLine.SalesPrice = cbCTInvoiceLine.Amount;
            salesLine.LineAmount = salesLine.SalesQty *  salesLine.SalesPrice;
            // The financial dimensions on the sales order lines will be copied from the charge through invoice
            salesLine.DefaultDimension = cbCTInvoiceLine.FinancialDimension;

            // Tax group initFromSalesTable which could be different, so update it after line is inserted
            salesLine.TaxGroup = cbCTInvoiceLine.TaxGroup;
            salesLine.TaxItemGroup = cbCTInvoiceLine.TaxItemGroup;

            salesLine.update();

            // CB411_412_ChargeThrough customer off remittance
            if (!searchMarkup)
            {
                // copy charges from vendor invoice to SO line
                this.copyChargesFromPendingVendorInvoice(salesLine, _vendInvoiceInfoTable);
            }

            // line document note attachment
            this.createNote(salesLine, _cbCTInvoiceHeaderTable);

        }

        return salesTable;
    }

    private SalesTable findOrCreateSalesOrderHeader(METCBCTInvoiceHeaderTable _cbCTInvoiceHeaderTable)
    {
        SalesTable  salesTable;
        METVendParameters metVendParameters = METVendParameters::find();
        
        // if summary SO invoice posting
        if (metVendParameters.CustInvoicePostingType)
        {
            // find open CT SO header
            select firstonly salesTable
                where salesTable.CustAccount == _cbCTInvoiceHeaderTable.CustomerAccount
                   && salesTable.SalesType ==  SalesType::Sales
                   && salesTable.METSalesOrderType == metVendParameters.SalesOrderType
                   && salesTable.SalesStatus == SalesStatus::Backorder;

            if (salesTable)
            {
                return SalesTable;
            }
        }
        
        NumberSeq   numberSeq = NumberSeq::newGetNum(SalesParameters::numRefSalesId());        
        CustTable   custTable = CustTable::find(_cbCTInvoiceHeaderTable.CustomerAccount);
        
        salesTable.clear();
        salesTable.initValue();
        salesTable.SalesType    =  SalesType::Sales;
        salesTable.CustAccount  = _cbCTInvoiceHeaderTable.CustomerAccount;
        salesTable.initFromCustTable();
        salesTable.SalesId      = numberSeq.num();
        salesTable.TaxGroup     = custTable.TaxGroup;
        salesTable.CashDisc     = _cbCTInvoiceHeaderTable.CustCashDisc;
        salesTable.CustomerRef  = _cbCTInvoiceHeaderTable.TaxInvoiceNum + ' '+
                                  _cbCTInvoiceHeaderTable.VendorAccount + ' '+
                                  _cbCTInvoiceHeaderTable.vendTable().name();
        salesTable.GUPSkipPricingCalculation = NoYes::Yes;
        salesTable.METSalesOrderType = metVendParameters.SalesOrderType;
        salesTable.DefaultDimension = _cbCTInvoiceHeaderTable.FinancialDimension;

        // CB194_ChargeThroughClaims
        // When the Sales Order is created, if there is a value present in the below field, copy it onto the respective field on the new Sales order header
        if (_cbCTInvoiceHeaderTable.ClaimReasonCodeId)
        {
            salesTable.ReturnReasonCodeId = _cbCTInvoiceHeaderTable.ClaimReasonCodeId;
        }
        salesTable.insert();

        return SalesTable;
    }

    /// <summary>
    /// create pending vendor invoice
    /// </summary>
    /// <param name="_cbCTInvoiceHeaderTable"><c>METCBCTInvoiceHeaderTable</c></param>
    /// <returns><c>VendInvoiceInfoTable</c> Pending vendor invoice header</returns>
    private VendInvoiceInfoTable createPendingVendorInvoice(METCBCTInvoiceHeaderTable  _cbCTInvoiceHeaderTable)
    {
        VendInvoiceInfoTable    vendInvoiceInfoTable;

        // CB194_ChargeThroughClaims only create pending vendor invoice if CT line with vendor type
        if (METCBCTInvoiceLine::existType(_cbCTInvoiceHeaderTable.Number, METCBCTVendCust::Vend))
        {
            vendInvoiceInfoTable = this.createPendingVendorInvoiceHeader(_cbCTInvoiceHeaderTable);

            this.createPendingVendorInvoiceLines(vendInvoiceInfoTable);        
        }

        return vendInvoiceInfoTable;
    }

    /// <summary>
    /// Create pending vendor invoice header
    /// </summary>
    /// <param name = "_cbCTInvoiceHeaderTable"><c>METCBCTInvoiceHeaderTable</c> charge through invoice header</param>
    /// <returns><c>VendInvoiceInfoTable</c> pending vendor invoice header</returns>
    private VendInvoiceInfoTable createPendingVendorInvoiceHeader(METCBCTInvoiceHeaderTable  _cbCTInvoiceHeaderTable)
    {
        VendInvoiceInfoTable    vendInvoiceInfoTable;
        VendTable               vendTable = VendTable::find(_cbCTInvoiceHeaderTable.VendorAccount);
        METVendTable            metVendTable = METVendTable::find(_cbCTInvoiceHeaderTable.VendorAccount);
        METVendParameters       metVendParameters = METVendParameters::find();

        vendInvoiceInfoTable.TableRefId             = formletterParmData::getNewTableRefId();

        vendInvoiceInfoTable.ParmJobStatus          = ParmJobStatus::Waiting;
        vendInvoiceInfoTable.VendInvoiceSaveStatus  = VendInvoiceSaveStatus::Pending;
        
        // CB411_412_ChargeThrough created initFrom methods
        vendInvoiceInfoTable.METInitFromCBCTInvoiceHeaderTable(_cbCTInvoiceHeaderTable);
        vendInvoiceInfoTable.METInitFromVendTable(vendTable);
        vendInvoiceInfoTable.METInitFromMETVendTable(metVendTable);

        vendInvoiceInfoTable.Description = vendInvoiceInfoTable.MetImportAmount >= 0 ? metVendParameters.VendInvoiceJournalNameCredit : metVendParameters.VendInvoiceJournalNameDebit;

        vendInvoiceInfoTable.defaultRow();
        if (vendInvoiceInfoTable.validateWrite())
        {
            // required before the vendInvoiceInfoTable.insert to fix error The state of the source document or source document line could not be updated.
            // when we have auto charges headers (Check form VendEditInvoice\VendInvoiceInfoTable_ds\write)
            VendInvoiceInfoSubTable::createFromVendInvoiceInfoTable(vendInvoiceInfoTable, true);
            
            vendInvoiceInfoTable.insert();
            info(strFmt("@MET:VendorInvoiceIsCreated",vendInvoiceInfoTable.Num));
        }
        else
        {
            error("@Proj:VendorInvoiceNotCreated");
        }

        return vendInvoiceInfoTable;
    }

    /// <summary>
    /// Create pending vendor invoice lines
    /// </summary>
    /// <param name = "_vendInvoiceInfoTable">Pending vendor invoice header</param>
    void createPendingVendorInvoiceLines(VendInvoiceInfoTable _vendInvoiceInfoTable)
    {
        METCBCTInvoiceLine      cbCTInvoiceLine;
        VendInvoiceInfoLine     vendInvoiceLine;
        RecordInsertList        vendInvoiceLineInsertList;

        vendInvoiceLineInsertList = new RecordInsertList(tableNum(VendInvoiceInfoLine));

        while select cbCTInvoiceLine
            where cbCTInvoiceLine.HeaderNumber == _vendInvoiceInfoTable.METCBCTNumber
               && cbCTInvoiceLine.VendCustType == METCBCTVendCust::Vend
        {
            vendInvoiceLine.clear();
            vendInvoiceLine.initValue();
            vendInvoiceLine.ParmId              = _vendInvoiceInfoTable.ParmId;
            vendInvoiceLine.TableRefId          = _vendInvoiceInfoTable.TableRefid;
            vendInvoiceLine.OrderAccount        = _vendInvoiceInfoTable.OrderAccount;
            vendInvoiceLine.currencyCode        = _vendInvoiceInfoTable.CurrencyCode;

            vendInvoiceLine.METInitFromCBCTInvoiceLine(cbCTInvoiceLine);

            vendInvoiceLine.PurchUnit           = METConstants::unitEach;
            vendInvoiceLine.modifiedField(fieldNum(VendInvoiceInfoLine, PurchPrice));

            vendInvoiceLineInsertList.add(vendInvoiceLine);
        }
        vendInvoiceLineInsertList.insertDatabase();
    }

    /// <summary>
    /// CB411_412_ChargeThrough Validate charge through invoice at processing time
    /// </summary>
    /// <param name = "_cbCTInvoiceHeaderTable">Charge through invoice header</param>
    /// <returns>True if validation successful; otherwise, false.</returns>
    boolean validate(METCBCTInvoiceHeaderTable  _cbCTInvoiceHeaderTable)
    {        
        boolean ret = true;
        METVendParameters metVendParameters = METVendParameters::find();

        // vendor invoice validation
        // Invoice date
        if (_cbCTInvoiceHeaderTable.DocumentDate > DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()) + metVendParameters.MaxInvoiceDays)
        {
            ret = checkFailed("@MET:CBCTInvoiceDateValidation");
        }

        if (_cbCTInvoiceHeaderTable.ManuallyCreated)
        { 
            // Allow CT or cross dock
            METVendTable metVendTable = METVendTable::find(_cbCTInvoiceHeaderTable.VendorAccount);

            if (!metVendTable.AllowChargeThrough && !metVendTable.AllowCrossDock)
            {
                ret = checkFailed("@MET:CBCTVendorAllowedValidation");
            }
        }

        return ret;
    }

/// <summary>
/// CB411_412_ChargeThrough Create notes against the sales order lines
/// </summary>
/// <param name = "_salesLine">Sales order line</param>
/// <param name = "_cbCTInvoiceHeaderTable">Charge through invoice header</param>
void createNote(SalesLine _salesLine, METCBCTInvoiceHeaderTable  _cbCTInvoiceHeaderTable)
{
    DocumentManagement::attachNote(
        _salesLine.TableId,
        _salesLine.RecId,
        _salesLine.DataAreaId,
        DocuType::typeNote(),
        "@MET:CBCT",
        strFmt("@MET:SalesLineCTNotes", _cbCTInvoiceHeaderTable.DocumentDate,
                                        _cbCTInvoiceHeaderTable.TaxInvoiceNum,
                                        _cbCTInvoiceHeaderTable.VendorAccount,
                                        _cbCTInvoiceHeaderTable.vendTable().name()));
}

    /// <summary>
    /// CB411_412_ChargeThrough Post sales order invoice
    /// </summary>
    /// <param name = "_salesTable">Sales order header</param>
    void postSalesOrderInvoice(SalesTable _salesTable)
    {
        METVendParameters metVendParameters = METVendParameters::find();

        // if detailed SO invoice posting
        if (!metVendParameters.CustInvoicePostingType)
        {
            // the charge through sales order is posted as part of the Charge through process function.
            SalesFormLetter salesFormLetter = SalesFormLetter::construct(DocumentStatus::Invoice);
            salesFormLetter.update(_salesTable);
        }
    }

/// <summary>
/// CB411_412_ChargeThrough Post pending vendor invoice
/// </summary>
/// <param name = "_vendInvoiceInfoTable">Pending vendor invoice header</param>
void submitVendorInvoiceWorkflow(VendInvoiceInfoTable _vendInvoiceInfoTable)
{
    if (_vendInvoiceInfoTable && _vendInvoiceInfoTable.canSubmitToWorkflow())
    {
        VendInvoiceHeaderWorkflow::submitToWorkflow(_vendInvoiceInfoTable, strFmt("@MET:CTAutoSubmitWorkflowComment", _vendInvoiceInfoTable.METCBCTNumber));
    }
}

    /// <summary>
    /// CB411_412_ChargeThrough Copy pending vendor invoice line charges to sales order line charges.
    /// </summary>
    /// <param name = "_salesLine">Sales order line</param>
    /// <param name = "_vendInvoiceInfoTable">Pending vendor invoice header</param>
    void copyChargesFromPendingVendorInvoice(SalesLine _salesLine, VendInvoiceInfoTable _vendInvoiceInfoTable)
    {
        VendInvoiceInfoLine vendInvoiceInfoLine;
        MarkupTrans       markUpTransVendInvoiceInfoLine, markUpTransSalesLine;
        LineNum           markUpTransSalesLineLineNum;
        RecordInsertList  markUpTransSalesLineRecordInsertList = new RecordInsertList(tableNum(MarkupTrans));
        
        select firstonly vendInvoiceInfoLine
                   where vendInvoiceInfoLine.ParmId     == _vendInvoiceInfoTable.ParmId
                      && vendInvoiceInfoLine.TableRefId == _vendInvoiceInfoTable.TableRefId
                      && vendInvoiceInfoLine.ItemId     == _salesLine.ItemId
                      && vendInvoiceInfoLine.TaxGroup   == _salesLine.TaxGroup;

        if (vendInvoiceInfoLine)
        {                
            markUpTransSalesLineLineNum = MarkupTrans::lastLineNum(_salesLine.TableId, _salesLine.RecId);

            while select markUpTransVendInvoiceInfoLine
                   where markUpTransVendInvoiceInfoLine.TransTableId == vendInvoiceInfoLine.TableId
                      && markUpTransVendInvoiceInfoLine.TransRecId == vendInvoiceInfoLine.RecId
            {
                markUpTransSalesLineLineNum++;
                markUpTransSalesLine.clear();
                markUpTransSalesLine.data(markUpTransVendInvoiceInfoLine);
                markUpTransSalesLine.TransTableId   = _salesLine.TableId;
                markUpTransSalesLine.TransRecId     = _salesLine.RecId;
                markUpTransSalesLine.LineNum        = markUpTransSalesLineLineNum;
                markUpTransSalesLineRecordInsertList.add(markUpTransSalesLine);
            }                
        }
        
        markUpTransSalesLineRecordInsertList.insertDatabase();
    }

    /// <summary>
    /// Count number of charge through to be processed
    /// </summary>
    /// <param name = "_query"><c>Query</c> object</param>
    /// <returns>Number of charge through to be processed</returns>
    protected int countChargeThrough(Query _query)
    {
        QueryBuildDataSource qbds = _query.dataSourceTable(tablenum(METCBCTInvoiceHeaderTable));
        qbds.addSelectionField(fieldNum(METCBCTInvoiceHeaderTable, RecId), SelectionField::Count);

        QueryRun qr = new QueryRun(_query);

        return SysQuery::countTotal(qr);
    }

    /// <summary>
    /// metho to update METCBCTInvoiceHeaderTable table
    /// Bug_188467_CB411_ChargethroughIssueFix
    /// </summary>
    /// <param name = "_cbctInvoiceHeadeTable">buffer of METCBCTInvoiceHeaderTable</param>
    /// <param name = "_isProcessed">boolean value to mention is process completed</param>
    public void updateMetCBCInvoiceHeader(METCBCTInvoiceHeaderTable _cbctInvoiceHeadeTable, boolean _isProcessed = true)
    {
        METCBCTInvoiceHeaderTable       cbctInvoiceHeadeTable = _cbctInvoiceHeadeTable;

        ttsbegin;
        cbctInvoiceHeadeTable.selectForUpdate(true);
        if(_isProcessed)
        {
            cbctInvoiceHeadeTable.Error             = NoYes::No;
            cbctInvoiceHeadeTable.ErrorDescription  = METConstants::emptyString;
        }
        else
        {
            cbctInvoiceHeadeTable.RefSalesId        = METConstants::emptyString;
            cbctInvoiceHeadeTable.Status            = METCBCTInvoiceStatus::Created;
        }
        cbctInvoiceHeadeTable.update();
        ttscommit;
    }
